def link_zones(apps, schema_editor):
    """Zones made from old areas inherit that area's OpenBeta links and rock type."""
    Zone = apps.get_model("adventures", "Zone")
    for zone in Zone.objects.all():
        placeholder = zone.crags.filter(name=zone.name).first()
        if placeholder:
            zone.openbeta_uuids = placeholder.openbeta_uuids
            zone.sandstone = placeholder.sandstone
            zone.save(update_fields=["openbeta_uuids", "sandstone"])


